<?php
require __DIR__ . '/config.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST, 'product_id', FILTER_VALIDATE_INT);
$stmt = $pdo->prepare('SELECT * FROM products WHERE id = ? AND stock > 0'); $stmt->execute([$id]); $product = $stmt->fetch();
if (!$product) { http_response_code(404); exit('Ժամացույցը չի գտնվել կամ արդեն վաճառված է։ <a href="index.php">Վերադառնալ</a>'); }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  $name = trim($_POST['customer_name'] ?? ''); $phone = trim($_POST['phone'] ?? ''); $message = trim($_POST['message'] ?? '');
  if ($name === '' || $phone === '') $error = 'Լրացրու անունը և հեռախոսահամարը։';
  else { $stmt = $pdo->prepare('INSERT INTO buy_requests (product_id, customer_name, phone, message) VALUES (?,?,?,?)'); $stmt->execute([$product['id'],$name,$phone,$message]); header('Location: buy.php?id='.(int)$product['id'].'&sent=1'); exit; }
}
$sent = isset($_GET['sent']);
?>
<!doctype html><html lang="hy"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Գնել ժամացույց — Ժամապահ</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><a class="logo" href="index.php"><span class="logo-mark">Ժ</span> ԺԱՄԱՊԱՀ</a><nav><a href="index.php">← Վերադառնալ խանութ</a><a href="sell.php" class="nav-sell">Վաճառել ժամացույցը ↗</a></nav></header><main class="form-page"><a class="back-link" href="index.php">← Բոլոր ժամացույցները</a><div class="buy-layout"><div class="buy-preview"><img src="assets/<?= e($product['image']) ?>" alt="<?= e($product['name']) ?>"><span class="eyebrow"><?= e($product['brand']) ?> · <?= e($product['type']) ?></span><h1><?= e($product['name']) ?></h1><p><?= e($product['description']) ?></p><strong class="big-price"><?= number_format((float)$product['price'],0,'.',' ') ?> ֏</strong></div><div class="form-panel"><p class="eyebrow">ԳՆՄԱՆ ՀԱՅՏ</p><h2>Պատվիրիր ժամացույցը</h2><?php if ($sent): ?><div class="success-box"><strong>Հայտն ուղարկված է։</strong><p>Շնորհակալություն։ Կապ կհաստատենք նշված հեռախոսահամարով։</p></div><?php else: ?><?php if($error): ?><div class="error-box"><?= e($error) ?></div><?php endif; ?><form method="post" class="stack-form"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><label>Անուն, ազգանուն<input name="customer_name" required value="<?= e($_POST['customer_name'] ?? '') ?>" placeholder="Օր.՝ Արամ Սարգսյան"></label><label>Հեռախոսահամար<input name="phone" required value="<?= e($_POST['phone'] ?? '') ?>" placeholder="+374 …"></label><label>Հաղորդագրություն <span class="optional">(պարտադիր չէ)</span><textarea name="message" rows="4" placeholder="Հարցեր կամ նախընտրելի ժամ... "><?= e($_POST['message'] ?? '') ?></textarea></label><button class="btn btn-dark btn-full" type="submit">Ուղարկել գնման հայտը ↗</button><p class="form-help">Սա հայտ է, ոչ թե ավտոմատ վճարում։ Վաճառողը կապ կհաստատի քեզ հետ։</p></form><?php endif; ?></div></div></main><footer><a class="logo" href="index.php"><span class="logo-mark">Ժ</span> ԺԱՄԱՊԱՀ</a><span>Ժամացույցների առք ու վաճառքի ուսումնական նախագիծ</span><span>© <?= date('Y') ?> ԺԱՄԱՊԱՀ</span></footer></body></html>
